#include <SPI.h>
#include <Adafruit_GFX.h>
#include <dragon.h>

SPIClass hspi(HSPI);

#define TFT_DC  2
#define TFT_CS  15
#define TFT_RST 4

dragon_ILI9341 tft(&hspi, TFT_DC, TFT_CS, TFT_RST);

bool open = true;
unsigned long next = 0;

void setup() {
  hspi.begin(14, 12, 13, 15);
  tft.begin();
  tft.fillScreen(ILI9341_BLACK);
  tft.display();
  delay(1000);
  randomSeed(millis());
  next = millis() + 3000;
}

void loop() {
  if (open && millis() >= next) {
    next = millis() + random(3000, 5000);
    open = false;
  }
  if (!open && millis() >= next + 120) {
    open = true;
  }
  tft.fillScreen(ILI9341_BLACK);
  if (open) {
    tft.fillCircle(80, 160, 18, ILI9341_BLUE);
    tft.fillCircle(120, 160, 18, ILI9341_BLUE);
  }
  tft.display();
  delay(50);
}
